const items = $input.all();

function normalizePath(value) {
  return String(value ?? '').trim().replace(/\\/g, '/');
}

function stripTrailingSlashes(value) {
  let result = value;
  while (result.length > 1 && result.endsWith('/')) {
    result = result.slice(0, -1);
  }
  return result;
}

function hasGlobPattern(value) {
  return ['*', '?', '[', ']', '{', '}'].some((char) => value.includes(char));
}

function fileNameFromPath(value) {
  const parts = value.split('/').filter(Boolean);
  return parts[parts.length - 1] || '';
}

function extensionOf(fileName) {
  const dotIndex = fileName.lastIndexOf('.');
  return dotIndex > 0 && dotIndex < fileName.length - 1
    ? fileName.slice(dotIndex + 1).toLowerCase()
    : '';
}

const legacyAllowedExtensions = new Set(['jpg', 'png', 'txt']);
const batchAllowedExtensions = new Set(['jpg', 'jpeg', 'png', 'webp']);
const output = [];
let batchInputIndex = 0;
const seenBatchPaths = new Set();

for (const [itemIndex, item] of items.entries()) {
  const input = item.json || {};
  const filePath = normalizePath(input.filePath);
  const folderPath = stripTrailingSlashes(normalizePath(input.folderPath));
  const hasFilePath = filePath !== '';
  const hasFolderPath = folderPath !== '';
  const hasFilePathsField = Object.prototype.hasOwnProperty.call(input, 'filePaths') && input.filePaths != null;

  if (hasFilePathsField && !Array.isArray(input.filePaths)) {
    throw new Error('filePaths must be an array for item ' + (itemIndex + 1));
  }

  const filePaths = Array.isArray(input.filePaths)
    ? input.filePaths.map(normalizePath).filter(Boolean)
    : [];
  const hasFilePaths = filePaths.length > 0;
  const modeCount = Number(hasFilePath) + Number(hasFolderPath) + Number(hasFilePaths);

  if (modeCount === 0) {
    throw new Error('Exactly one of filePath, folderPath, or a non-empty filePaths array is required for item ' + (itemIndex + 1));
  }

  if (modeCount > 1) {
    throw new Error('Only one of filePath, folderPath, or filePaths can be provided for item ' + (itemIndex + 1));
  }

  if (hasFilePaths) {
    for (const currentPath of filePaths) {
      if (hasGlobPattern(currentPath)) {
        throw new Error('filePaths entries must point to concrete files, not glob patterns: ' + currentPath);
      }
      const fileName = fileNameFromPath(currentPath);
      const fileExtension = extensionOf(fileName);
      if (!batchAllowedExtensions.has(fileExtension)) {
        throw new Error('Unsupported batch file extension "' + (fileExtension || 'none') + '" for ' + currentPath + '. Supported: .jpg, .jpeg, .png, .webp');
      }
      const dedupeKey = currentPath.toLowerCase();
      if (seenBatchPaths.has(dedupeKey)) {
        throw new Error('Duplicate path in filePaths: ' + currentPath);
      }
      seenBatchPaths.add(dedupeKey);
      output.push({
        json: {
          filePath: currentPath,
          folderPath: '',
          fileSelector: currentPath,
          inputMode: 'batch',
          fileName,
          fileExtension,
          inputIndex: batchInputIndex,
        },
      });
      batchInputIndex += 1;
    }
    continue;
  }

  if (hasFilePath) {
    if (hasGlobPattern(filePath)) {
      throw new Error('filePath must point to one concrete file, not a glob pattern, for item ' + (itemIndex + 1));
    }

    const fileName = fileNameFromPath(filePath);
    const fileExtension = extensionOf(fileName);

    if (!legacyAllowedExtensions.has(fileExtension)) {
      throw new Error('Unsupported file extension "' + (fileExtension || 'none') + '" for item ' + (itemIndex + 1) + '. Supported: .jpg, .png, .txt');
    }

    output.push({
      json: {
        filePath,
        folderPath: '',
        fileSelector: filePath,
        inputMode: 'file',
        fileName,
        fileExtension,
        inputIndex: itemIndex,
      },
    });
    continue;
  }

  output.push({
    json: {
      filePath: '',
      folderPath,
      fileSelector: folderPath + '/*.{jpg,JPG,png,PNG,txt,TXT}',
      inputMode: 'folder',
      allowedFileTypes: ['jpg', 'png', 'txt'],
      sortRule: 'jpg,png,txt; natural filename order inside each type',
      inputIndex: itemIndex,
    },
  });
}

return output;

const uploadItems = $input.all();
const sortedItems = $('Sort Files').all();

function cleanString(value) {
  return String(value ?? '').trim();
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(cleanString(value));
}

if (uploadItems.length !== sortedItems.length) {
  throw new Error('SiliconFlow upload result count mismatch: expected ' + sortedItems.length + ', received ' + uploadItems.length);
}

const records = uploadItems.map((item, index) => {
  const response = item.json || {};
  const data = response.data || {};
  const sorted = sortedItems[index]?.json || {};
  const sourceFileName = cleanString(sorted.fileName || sorted.filePath || 'item ' + (index + 1));
  const inputMode = cleanString(sorted.inputMode) || 'file';

  if (response.status === false) {
    throw new Error('SiliconFlow upload failed for ' + sourceFileName + ': ' + (response.message || 'unknown error'));
  }

  if (response.code && Number(response.code) !== 20000) {
    throw new Error('SiliconFlow upload returned code ' + response.code + ' for ' + sourceFileName + ': ' + (response.message || 'unknown error'));
  }

  const url = cleanString(data.object || data.url || response.url);
  if (!url) {
    throw new Error('SiliconFlow upload response is missing URL for ' + sourceFileName);
  }
  if (!isHttpUrl(url)) {
    throw new Error('SiliconFlow upload returned a non-HTTP URL for ' + sourceFileName);
  }

  return {
    fileName: cleanString(data.filename || sorted.fileName || 'file_' + (index + 1)),
    sourceFileName,
    inputMode,
    inputIndex: Number(sorted.inputIndex),
    url,
  };
});

return records.map((record, index) => ({
  json: record.inputMode === 'batch'
    ? {
        ['\u6587\u4ef6\u540d']: record.fileName,
        url: record.url,
        sourceFileName: record.sourceFileName,
        inputIndex: record.inputIndex,
      }
    : {
        ['\u6587\u4ef6\u540d']: record.fileName,
        url: record.url,
      },
  pairedItem: { item: index },
}));

const items = $input.all();
const preparedItems = $('Prepare Input').all();
const collator = new Intl.Collator('zh-CN', { numeric: true, sensitivity: 'base' });

function cleanString(value) {
  return String(value ?? '').trim();
}

function extensionOf(fileName, fallback = '') {
  const name = cleanString(fileName);
  const dotIndex = name.lastIndexOf('.');
  const ext = dotIndex > 0 && dotIndex < name.length - 1 ? name.slice(dotIndex + 1) : fallback;
  return cleanString(ext).toLowerCase();
}

function fileTypeRank(extension) {
  if (extension === 'jpg') return 1;
  if (extension === 'png') return 2;
  if (extension === 'txt') return 3;
  return 99;
}

function pairedInputIndex(item, fallback) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const value = Number(paired?.item);
  return Number.isInteger(value) && value >= 0 ? value : fallback;
}

const prepared = items.map((item, originalIndex) => {
  const sourceIndex = pairedInputIndex(item, originalIndex);
  const sourceJson = preparedItems[sourceIndex]?.json || {};
  const json = { ...sourceJson, ...(item.json || {}) };
  const binaryData = item.binary?.data || {};
  const inputMode = cleanString(json.inputMode) || 'file';
  const fileName = cleanString(json.fileName || binaryData.fileName || 'file_' + (originalIndex + 1));
  const fileExtension = extensionOf(fileName, json.fileExtension || binaryData.fileExtension);
  const allowed = inputMode === 'batch'
    ? ['jpg', 'jpeg', 'png', 'webp'].includes(fileExtension)
    : ['jpg', 'png', 'txt'].includes(fileExtension);
  return {
    item,
    originalIndex,
    inputMode,
    inputIndex: Number.isInteger(Number(json.inputIndex)) ? Number(json.inputIndex) : originalIndex,
    fileName,
    fileExtension,
    typeRank: fileTypeRank(fileExtension),
    allowed,
  };
}).filter((entry) => entry.allowed);

prepared.sort((a, b) => {
  if (a.inputMode === 'batch' && b.inputMode === 'batch') {
    return a.inputIndex - b.inputIndex;
  }
  if (a.inputMode === 'batch') return 1;
  if (b.inputMode === 'batch') return -1;
  if (a.typeRank !== b.typeRank) return a.typeRank - b.typeRank;
  const byName = collator.compare(a.fileName, b.fileName);
  if (byName !== 0) return byName;
  return a.originalIndex - b.originalIndex;
});

return prepared.map((entry, sortedIndex) => ({
  json: {
    ...entry.item.json,
    inputMode: entry.inputMode,
    inputIndex: entry.inputIndex,
    fileName: entry.fileName,
    fileExtension: entry.fileExtension,
    sortIndex: sortedIndex + 1,
    originalIndex: entry.originalIndex + 1,
  },
  binary: entry.item.binary,
  pairedItem: entry.item.pairedItem,
}));
